(() => {
  // packages/djaker-hakim/stm-ui-components/dist/stm-script.js
  window.$stm = {
    list: [],
    register(component) {
      this.list.push(component);
    },
    unregister(id) {
      this.list = this.list.filter((item) => item.id != id);
    },
    component(id) {
      return this.list.find((item) => item.id == id);
    },
    ref(ref) {
      if (ref == "") return;
      return this.list.find((item) => item.ref == ref);
    },
    get(idOrRef) {
      if (this.component(idOrRef)) return this.component(idOrRef);
      if (this.ref(idOrRef)) return this.ref(idOrRef);
      return void 0;
    },
    allComponents() {
      return this.list;
    },
    open(id) {
      this.get(id).open();
    },
    close(id) {
      this.get(id).close();
    },
    toggle(id) {
      this.get(id).toggle();
    },
    getState(id) {
      return this.get(id).state;
    }
  };

  // packages/djaker-hakim/stm-ui-components/dist/traits/refTrait.js
  var refTrait = {
    ref: null,
    setRef() {
      const root = this.$root;
      let el = null;
      if (root.hasAttribute("stm-ref")) {
        this.ref = root.getAttribute("stm-ref");
      } else if (el = root.querySelector("[stm-ref]")) {
        this.ref = el.getAttribute("stm-ref");
      }
    }
  };

  // packages/djaker-hakim/stm-ui-components/dist/traits/stmInitTrait.js
  var stmInitTrait = {
    ...refTrait,
    stmInit() {
      this.setRef();
      $stm.register(this);
    }
  };

  // packages/djaker-hakim/stm-ui-components/dist/form/error.js
  window.$stm.error = (id, message) => {
    return {
      ...stmInitTrait,
      id,
      message,
      init() {
        this.stmInit();
      },
      setMessage(message2) {
        this.message = message2;
      },
      reset() {
        this.message = "";
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/form/password.js
  window.$stm.password = (id, config) => {
    return {
      ...stmInitTrait,
      id,
      type: "password",
      state: config.state,
      showButton: config.showButton,
      init() {
        this.stmInit();
      },
      show() {
        this.state = true;
      },
      hide() {
        this.state = false;
      },
      toggle() {
        this.state = !this.state;
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/form/select.js
  window.$stm.select = (id, options, selected = "") => {
    return {
      ...stmInitTrait,
      id,
      type: "select",
      options: [],
      selected: "",
      init() {
        this.stmInit();
        this.options = options;
        selected ? this.selected = selected : "";
      },
      getSelection() {
        return this.$root.value;
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/traits/stateTrait.js
  var stateTrait = {
    open(obj = "") {
      if (obj) {
        this.id == obj.id || this.ref == obj.ref ? this.state = true : "";
      } else {
        this.state = true;
      }
    },
    close(obj = "") {
      if (obj) {
        this.id == obj.id || this.ref == obj.ref ? this.state = false : "";
      } else {
        this.state = false;
      }
    },
    toggle(obj = "") {
      if (obj) {
        this.id == obj.id || this.ref == obj.ref ? this.state = !this.state : "";
      } else {
        this.state = !this.state;
      }
    },
    getState() {
      return this.state;
    }
  };

  // packages/djaker-hakim/stm-ui-components/dist/ui/alert.js
  window.$stm.alert = (id, config) => {
    return {
      ...stmInitTrait,
      id,
      type: "alert",
      state: config.state,
      ...stateTrait,
      content: config.content,
      mode: config.mode,
      init() {
        this.stmInit();
        window.addEventListener("open-alert", (e) => this.open(e.detail));
        window.addEventListener("close-alert", (e) => this.close(e.detail));
        window.addEventListener("toggle-alert", (e) => this.toggle(e.detail));
      },
      setContent(content, mode) {
        this.mode = mode;
        this.content = content;
      },
      error(content) {
        this.setContent(content, "error");
        return this;
      },
      info(content) {
        this.setContent(content, "info");
        return this;
      },
      warn(content) {
        this.setContent(content, "warning");
        return this;
      },
      success(content) {
        this.setContent(content, "success");
        return this;
      },
      openTmp(duration = 4e3) {
        this.open();
        const alert = setTimeout(() => {
          this.close();
        }, duration);
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/ui/collapse.js
  window.$stm.collapse = (id, config) => {
    return {
      ...stmInitTrait,
      id,
      type: "collapse",
      state: config.state,
      ...stateTrait,
      init() {
        this.stmInit();
        window.addEventListener("open-collapse", (e) => this.open(e.detail));
        window.addEventListener("close-collapse", (e) => this.close(e.detail));
        window.addEventListener("toggle-collapse", (e) => this.toggle(e.detail));
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/traits/clickoutsideTrait.js
  var clickOutsideTrait = {
    clickOutsideFn() {
      if (this.clickOutside) this.close();
    }
  };

  // packages/djaker-hakim/stm-ui-components/dist/ui/dropdown.js
  window.$stm.dropdown = (id, config) => {
    return {
      ...stmInitTrait,
      id,
      type: "dropdown",
      state: config.state,
      ...stateTrait,
      clickOutside: config.clickOutside,
      ...clickOutsideTrait,
      init() {
        this.stmInit();
        window.addEventListener("open-dropdown", (e) => this.open(e.detail));
        window.addEventListener("close-dropdown", (e) => this.close(e.detail));
        window.addEventListener("toggle-dropdown", (e) => this.toggle(e.detail));
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/ui/modal.js
  window.$stm.modal = (id, config) => {
    return {
      ...stmInitTrait,
      id,
      state: config.state,
      ...stateTrait,
      clickOutside: config.clickOutside,
      ...clickOutsideTrait,
      init() {
        this.stmInit();
        window.addEventListener("open-modal", (e) => this.open(e.detail));
        window.addEventListener("close-modal", (e) => this.close(e.detail));
        window.addEventListener("toggle-modal", (e) => this.toggle(e.detail));
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/ui/pagination.js
  window.$stm.pagination = (id, config) => {
    return {
      ...stmInitTrait,
      id,
      currentPage: config.currentPage,
      totalPages: config.pages,
      pages: [],
      start: null,
      end: null,
      limit: config.limit,
      init() {
        this.stmInit();
        this.visiblePages();
      },
      next() {
        if (this.currentPage < this.totalPages) {
          this.currentPage++;
          this.visiblePages();
          this.sendEvent();
        }
      },
      prev() {
        if (this.currentPage > 1) {
          this.currentPage--;
          this.visiblePages();
          this.sendEvent();
        }
      },
      selectPage(page) {
        this.currentPage = page;
        this.visiblePages();
        this.sendEvent();
      },
      visiblePages() {
        this.pages = [];
        this.start = Math.max(1, this.currentPage - Math.floor(this.limit / 2));
        this.end = Math.min(this.totalPages, this.start + this.limit - 1);
        this.start = Math.max(1, this.end - this.limit + 1);
        for (let i = this.start; i <= this.end; i++) {
          this.pages.push(i);
        }
      },
      setLimit(value) {
        this.limit = value;
        this.visiblePages();
      },
      setTotalPages(value) {
        this.totalPages = value;
        this.visiblePages();
      },
      sendEvent() {
        this.$dispatch("change-page", { id: this.id, page: this.currentPage });
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/ui/progressbar.js
  window.$stm.progressBar = (id, config) => {
    return {
      ...stmInitTrait,
      id,
      type: "progressbar",
      lable: "",
      progress: 0,
      target: 0,
      pourcentage: config.pourcentage,
      duration: config.duration,
      interval: null,
      init() {
        this.stmInit();
        this.setProgress(config.progress);
      },
      validateProgress(value) {
        if (isNaN(Number(value))) return 0;
        value = Number(value);
        value = value < 0 ? 0 : value;
        value = value > 100 ? 100 : value;
        return value;
      },
      setProgress(value) {
        if (value == "infinite") {
          this.progress = -1;
          return;
        }
        value = this.validateProgress(value);
        if (this.progress > value) this.progress = 0;
        this.target = value;
        clearInterval(this.interval);
        this.interval = setInterval(() => {
          if (this.progress >= this.target) {
            clearInterval(this.interval);
            return;
          }
          this.progress += 1;
        }, this.duration);
      },
      setLable(value) {
        this.lable = value;
      },
      setDuration(value) {
        this.duration = value;
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/ui/sidebar.js
  window.$stm.sideBar = (id, config) => {
    return {
      ...stmInitTrait,
      id,
      type: "sidebar",
      state: config.state,
      ...stateTrait,
      breakpoint: config.breakpoint,
      init() {
        this.stmInit();
        window.addEventListener("open-sidebar", (e) => this.open(e.detail));
        window.addEventListener("close-sidebar", (e) => this.close(e.detail));
        window.addEventListener("toggle-sidebar", (e) => this.toggle(e.detail));
        this.checkSize();
        window.addEventListener("resize", (e) => this.checkSize());
      },
      checkSize() {
        if (window.innerWidth < this.breakpoint.width) {
          this.state = false;
        } else {
          this.state = true;
        }
      },
      clickOutsideFn() {
        if (this.breakpoint.clickOutside) {
          if (window.innerWidth < this.breakpoint.width) this.close();
        }
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/ui/table.js
  window.$stm.table = (id, data, config) => {
    return {
      ...stmInitTrait,
      id,
      type: "table",
      rows: [],
      selection: [],
      load: false,
      selectable: false,
      selectAllBtn: null,
      sortable: true,
      sortProps: {},
      cardHeader: [],
      headers: {},
      allHeaders: {},
      init() {
        this.selectable = config.selectable;
        this.selectAllBtn = config.selectAllBtn;
        this.sortable = config.sortable;
        this.loading(config.loading);
        this.setupData(data);
        this.stmInit();
      },
      setupData(rows) {
        this.setDefaultHeaders(rows);
        this.setHeaders(config.table.headers);
        this.setCardHeader(config.table.headers);
        this.setData(rows);
      },
      setData(rows) {
        this.sortProps.unsortedRows = rows.slice();
        this.rows = rows.slice();
      },
      setDefaultHeaders(rows) {
        if (rows.length > 0) {
          Object.keys(rows[0]).map((key2) => this.allHeaders[key2] = key2);
          return;
        }
        this.allHeaders = {};
      },
      setHeaders(headers2) {
        if (Object.keys(headers2).length > 0) {
          this.headers = headers2;
          return;
        }
        this.headers = this.allHeaders;
      },
      setCardHeader(header) {
        this.cardHeader = [];
        let obj = this.headers;
        if (Object.keys(header).length > 0) {
          obj = header;
          this.cardHeader.push(Object.keys(obj)[0], Object.values(obj)[0]);
          return;
        }
        obj = this.headers;
        this.cardHeader.push(Object.keys(obj)[0], Object.values(obj)[0]);
      },
      removeSelect() {
        this.selectable = false;
        this.selection = [];
      },
      showSelect() {
        this.selectable = true;
        this.selection = [];
      },
      toggleSelect() {
        this.selectable = !this.selectable;
        this.selection = [];
      },
      select(row) {
        this.selection.includes(row) ? this.selection = this.selection.filter((r) => r !== row) : this.selection.push(row);
      },
      selectAll() {
        this.selection = this.selection.length === this.rows.length ? [] : this.rows;
      },
      getSelection() {
        return this.selection;
      },
      sortBy(key2) {
        if (!this.sortable || !this.rows.length > 0) return;
        if (this.sortProps.key == key2) {
          this.sortProps.order = this.sortProps.order === "asc" ? "desc" : "unsort";
          this.sortProps.order === "unsort" ? this.sortProps.key = "" : "";
          this.sortRows(key2, this.sortProps.order);
          return;
        }
        this.sortProps.order = "asc", this.sortProps.key = key2;
        this.sortRows(key2, this.sortProps.order);
      },
      sortRows(key2, order) {
        if (order == "unsort") {
          this.rows = this.sortProps.unsortedRows.slice();
          return;
        }
        this.rows = this.rows.sort(
          (a, b) => {
            if (order === "asc") {
              if (a[key2] === b[key2]) return 0;
              return a[key2] < b[key2] ? -1 : 1;
            } else if (order === "desc") {
              if (a[key2] === b[key2]) return 0;
              return a[key2] > b[key2] ? -1 : 1;
            }
          }
        );
      },
      loading(state = true) {
        this.load = state;
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/ui/tabs.js
  window.$stm.tabs = (id, data, config = []) => {
    return {
      ...stmInitTrait,
      id,
      tabs: data,
      // array of object label, value, target, disabled
      activeTab: "",
      init() {
        this.stmInit();
        this.$watch("activeTab", (value) => {
          this.tabs.forEach((tab) => {
            if (tab.value == this.activeTab) {
              document.querySelector(tab.target).removeAttribute("style");
            } else {
              document.querySelector(tab.target).setAttribute("style", "display:none;");
            }
          });
        });
        this.activateDefault();
      },
      activate(value) {
        if (value == "unknown") {
          this.activeTab = value;
          return;
        }
        if (this.checkIfDisabled(this.findTab(value))) return;
        this.activeTab = value;
      },
      findTab(value) {
        let [tab] = this.tabs.filter((tab2) => {
          return tab2.value == value;
        });
        return tab;
      },
      disable(value) {
        let tab = this.findTab(value);
        tab.disabled = true;
        if (this.activeTab == tab.value) {
          this.activateDefault();
        }
      },
      enable(value) {
        let tab = this.findTab(value);
        tab.disabled = false;
        if (this.activeTab == "unknown") this.activate(tab.value);
      },
      checkIfDisabled(tab) {
        if (tab.hasOwnProperty("disabled")) return tab.disabled == true;
        return false;
      },
      getDefaultTab() {
        let defaultTab = { value: "unknown" };
        for (let i = 0; i < this.tabs.length; i++) {
          if (!this.checkIfDisabled(this.tabs[i])) {
            defaultTab = this.tabs[i];
            break;
          }
        }
        return defaultTab;
      },
      activateDefault() {
        this.activate(this.getDefaultTab().value);
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/master/datatable-script.js
  window.$stm.dataTable = (id, data, config) => {
    return {
      ...stmInitTrait,
      id,
      type: "datatable",
      data: null,
      allRows: [],
      rows: [],
      table: { allHeaders: {}, headers: {} },
      navigation: {
        columns: {},
        orderedColumns: {},
        search: ""
      },
      pagination: null,
      pageControl: {
        perPage: 5,
        pages: 0,
        currentPage: 1,
        start: 0,
        end: 0,
        dataLength: 0,
        paginate: true
      },
      init() {
        this.$nextTick(() => {
          this.setInitData(data);
          this.setConfig(config);
          this.setColumns();
          this.setFinalData();
          this.stmInit();
        });
      },
      setConfig(config2) {
        this.table = $stm.component(config2.tableId);
        this.pageControl.paginate = !(config2.pagination == "none");
        if (this.pageControl.paginate) {
          this.pagination = $stm.component(config2.paginationId);
          this.pageControl.perPage = Number(Object.keys(config2.navigation.perPageOptions)[0]);
        }
      },
      toggleHeaders(key2) {
        headers = new Map(Object.entries(this.headers));
        headers.has(key2) ? this.removeHeader(key2) : this.addHeader(key2);
      },
      addHeader(key2) {
        let headers2 = {};
        let keys = Object.keys(this.navigation.orderedColumns);
        keys.forEach((itemKey) => {
          if (itemKey == key2 || Object.keys(this.headers).includes(itemKey)) {
            headers2[itemKey] = this.navigation.orderedColumns[itemKey];
          }
        });
        this.table.setHeaders(headers2);
        this.headers = this.table.headers;
      },
      removeHeader(key2) {
        headers = new Map(Object.entries(this.headers));
        headers.delete(key2);
        this.table.setHeaders(Object.fromEntries(headers.entries()));
        this.headers = this.table.headers;
      },
      setColumns() {
        let headers2 = {};
        this.table.setupData(this.data);
        Object.keys(this.table.allHeaders).forEach((key2) => {
          Object.keys(this.table.headers).includes(key2) ? headers2[key2] = this.table.headers[key2] : headers2[key2] = this.table.allHeaders[key2];
        });
        this.headers = this.table.headers;
        this.navigation.columns = headers2;
        this.navigation.orderedColumns = headers2;
      },
      changeOrder(item, position) {
        let columns = {};
        let order = Object.keys(this.navigation.orderedColumns);
        order.splice(order.indexOf(item), 1);
        order.splice(position, 0, item);
        order.forEach((key2) => {
          columns[key2] = this.navigation.columns[key2];
        });
        this.navigation.orderedColumns = columns;
        this.applyOrder();
      },
      applyOrder() {
        let headers2 = {};
        let keys = Object.keys(this.navigation.orderedColumns);
        keys.forEach((key2) => {
          if (Object.keys(this.headers).includes(key2)) {
            headers2[key2] = this.navigation.orderedColumns[key2];
          }
        });
        this.table.setHeaders(headers2);
        this.headers = this.table.headers;
      },
      searchBy(text, filters) {
        if (text == "") return this.allRows;
        let rows = this.allRows.filter((row) => {
          let status = false;
          for (key in filters) {
            console.log("datatable null");
            if (row[key] === null) {
              status ||= false;
            } else {
              status ||= row[key].toString().toLowerCase().indexOf(text.trim().toLowerCase()) != -1;
            }
          }
          return status;
        });
        this.allRows = rows;
        return rows;
      },
      setInitData(rows) {
        this.data = rows;
      },
      setData(rows) {
        this.data = rows;
        this.setColumns();
        this.setFinalData();
      },
      paginate(page) {
        const control = this.pageControl;
        control.currentPage = Number(page);
        control.start = control.perPage * (control.currentPage - 1);
        control.end = Math.min(control.perPage * control.currentPage - 1, control.dataLength);
        let rows = this.allRows.slice(control.start, control.end + 1);
        this.rows = rows;
        this.table.setData(rows);
        return rows;
      },
      setPagination() {
        const control = this.pageControl;
        control.dataLength = this.allRows.length;
        control.pages = Math.ceil(control.dataLength / control.perPage);
        this.pagination.setTotalPages(control.pages);
        this.pagination.currentPage = 1;
        this.paginate(1);
      },
      setFinalData() {
        this.allRows = this.data;
        this.searchBy(this.navigation.search, this.table.headers);
        if (this.pageControl.paginate) {
          this.setPagination();
        } else {
          this.table.setData(this.allRows);
        }
      },
      setSearch(text) {
        this.navigation.search = text;
        this.setFinalData();
      },
      setPerPage(number) {
        number = Number(number);
        this.pageControl.perPage = isNaN(number) ? 10 : number;
        this.setFinalData();
      },
      loading(state = true) {
        this.table.loading(state);
      }
    };
  };

  // packages/djaker-hakim/stm-ui-components/dist/master/router.js
  window.$stm.router = (id) => {
    return {
      id,
      type: "router",
      route: "",
      params: {},
      init() {
        $stm.register(this);
        this.load();
        window.addEventListener("popstate", (e) => {
          this.load();
        });
      },
      href(link) {
        history.pushState({}, "", link);
        this.load();
      },
      url(pathname, params) {
        url = new URL(location);
        url.pathname = pathname;
        url.search = this.setSearchParams(params);
        this.href(url);
      },
      setSearchParams(params) {
        const searchParams = new URLSearchParams();
        for (const key2 in params) {
          searchParams.set(key2, params[key2]);
        }
        return searchParams.toString();
      },
      load() {
        this.route = location.pathname;
        const params = new URLSearchParams(location.search);
        this.params = Object.fromEntries(params.entries());
      },
      getCurrentRoute() {
        return this.route;
      },
      getParams() {
        return this.params;
      }
    };
  };
})();
